import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"2026-10-23「科学日报」18 条逐条核实","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/science-news/news-verification-2026-10-23.md","filePath":"topics/science-news/news-verification-2026-10-23.md"}'),g={name:"topics/science-news/news-verification-2026-10-23.md"};function e(a,t,i,l,d,u){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_2026-10-23「科学日报」18-条逐条核实" tabindex="-1">2026-10-23「科学日报」18 条逐条核实 <a class="header-anchor" href="#_2026-10-23「科学日报」18-条逐条核实" aria-label="Permalink to &quot;2026-10-23「科学日报」18 条逐条核实&quot;">​</a></h1><blockquote><p><strong>来源</strong>：用户 2026-10-23 18:00 转来的一条五段式科学新闻摘要（18 条，AI 段标注&quot;36kr&quot;）。 <strong>已确认这条不是本机 cron 生成的</strong> —— 本机 cron 只有 09:00 那期（Nature/Science 论文带 DOI），知识库与 ScienceDaily 仓库里都 grep 不到这 18 条。 <strong>核实方法</strong>：Google News RSS 定位原始报道 → 抓原文正文 → CrossRef API 核 DOI → PubMed E-utilities 核论文。 <strong>总判断</strong>：<strong>18/18 条都有真实来源，但转述普遍失真</strong>。失真分三类：</p></blockquote><table tabindex="0"><thead><tr><th>失真类型</th><th>条数</th><th>典型</th></tr></thead><tbody><tr><td><strong>时间错位</strong>（旧闻当今日）</td><td>8</td><td>USC 抗癌（6月）、双黑洞（4月）、水制氢（2–5月）、超流体比特（8月）、黎曼猜想（8月）、ChatGPT 小队（9月）</td></tr><tr><td><strong>程度夸大</strong>（预测/模型 → 已实现）</td><td>6</td><td>67.25% → &quot;破解黎曼猜想&quot;；模型预测 40 倍 → &quot;效率大幅提升&quot;；理论计算 100 倍 → &quot;已降低100倍&quot;</td></tr><tr><td><strong>主体/口径/方向错位</strong></td><td>4</td><td>相机锐度 → &quot;日冕仪&quot;；GFAP → &quot;FOXD1&quot;；&quot;向下逆转&quot; → &quot;大幅反弹&quot;（方向读反）</td></tr></tbody></table><blockquote><p>关键词：科学新闻核实、信源核实、36kr 标题党、时间错位、程度夸大、主体错位、黎曼猜想 67.25、TheoPhysEval、GPT-6 Astra、Zanvastro、GFAP、Alexander 病、GIMLI、钍-229 核时钟、BVR-19、SHOQ、DT-109</p></blockquote><hr><h2 id="📌-一页速查-真实出处-doi" tabindex="-1">📌 一页速查（真实出处 + DOI） <a class="header-anchor" href="#📌-一页速查-真实出处-doi" aria-label="Permalink to &quot;📌 一页速查（真实出处 + DOI）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>中文声明（节选）</th><th>真实出处</th><th>日期</th><th>DOI / 标识</th><th>主要失真</th></tr></thead><tbody><tr><td>生1</td><td>USC 无限量产抗癌免疫细胞</td><td><strong>Cell</strong>，USC Stem Cell 应其龙实验室</td><td>论文 2026-06</td><td><code>10.1016/j.cell.2026.05.043</code></td><td>实为 <strong>CAR-巨噬细胞</strong>；&quot;无限量产&quot;是标题党</td></tr><tr><td>生2</td><td>30年致命脑病首个有效药（<strong>FOXD1</strong>）</td><td>FDA 批准 <strong>Zanvastro（zilganersen）</strong>，Ionis</td><td>2026-09-03</td><td>商品名 Zanvastro™</td><td><strong>基因名错：GFAP，非 FOXD1</strong></td></tr><tr><td>生3</td><td>修菌群逆转严重脂肪肝</td><td><strong>J Clin Invest</strong> 136(13):e200522，DT-109</td><td>2026-05-12</td><td><code>10.1172/JCI200522</code></td><td>&quot;逆转&quot;→ 原文 alleviated；机制是抑制产氨菌</td></tr><tr><td>生4</td><td>47年追踪·肌肉力量从某年龄加速流失</td><td><strong>J Cachexia Sarcopenia Muscle</strong>，Karolinska</td><td>2025-16(6):e70134</td><td><code>10.1002/jcsm.70134</code></td><td>峰值是<strong>区间 26–36 岁</strong>；非&quot;肌肉力量&quot;是&quot;体能&quot;</td></tr><tr><td>太1</td><td>罗马望远镜日冕仪开光·超预期近30%</td><td>NASA Roman blog</td><td>2026-10-14</td><td>发射 <strong>2026-08-30</strong></td><td><strong>30% 属 WFI（90→63 nm），非日冕仪</strong></td></tr><tr><td>太2</td><td>双黑洞 100 年内相撞</td><td>MPIfR（Silke Britzen），<strong>MNRAS 接收</strong></td><td>2026-04 起</td><td>DOI 未入 CrossRef</td><td>是 <strong>Mrk 501 单星系</strong>的间接推断</td></tr><tr><td>太3</td><td>首台钍-229 核时钟问世</td><td><strong>Nature</strong> 658:897-902 / 658:903-908</td><td>2026-10-07</td><td><code>...s41586-026-11084-4</code> / <code>...s41586-026-11122-1</code></td><td><strong>两家同日各自实现</strong>；&quot;重新定义秒&quot;是远期设想</td></tr><tr><td>太4</td><td>NASA 启动月球洞穴勘探</td><td>PSI 牵头 <strong>GIMLI</strong> 项目立项</td><td>2026-09-30</td><td>—</td><td>仅<strong>立项未发射</strong>；熔岩管从未被证实</td></tr><tr><td>材1</td><td>水制氢新催化路径·绿氢成本再降</td><td><strong>JACS</strong>，Oregon State（BVR-19 MOF）</td><td>2026-09-14</td><td><code>10.1021/jacs.6c13238</code></td><td><strong>无任何实测成本数字</strong>，只是设计蓝图</td></tr><tr><td>材2</td><td>单原子&quot;量子高速公路&quot;·电流承载破极限</td><td><strong>Phys. Rev. B 114</strong>，NIMS MANA</td><td>2026-07-30</td><td><code>10.1103/b2j3-xj19</code></td><td><strong>定性错误</strong>：讲的是涡旋各向异性运动</td></tr><tr><td>材3</td><td>AI 挖出 CO₂→燃料捷径·效率大幅提升</td><td><strong>Nat. Commun.</strong>，IISc</td><td>2026-09-17</td><td><code>10.1038/s41467-026-77080-4</code></td><td>40 倍是<strong>模型预测</strong>非实测；AI 只是其中一环</td></tr><tr><td>材4</td><td>新量子比特错误率降 100 倍</td><td><strong>npj Quantum Information</strong>，Surrey（SHOQ）</td><td>2026-08-24</td><td><code>10.1038/s41534-026-01355-3</code></td><td><strong>器件未造</strong>；100 倍是理论计算</td></tr><tr><td>AI1</td><td>AI 再破广义黎曼猜想</td><td>Anthropic 研究</td><td>2026-08-10</td><td>—</td><td><strong>未发布模型</strong>、<strong>窄结论</strong>、无同行评议</td></tr><tr><td>AI2</td><td>ChatGPT 升级&quot;AI 小队&quot;</td><td>OpenAI 发布 <strong>Dots + Space</strong></td><td><strong>2026-09-29</strong></td><td>—</td><td>时间错位；官方名非&quot;AI 小队&quot;</td></tr><tr><td>AI3</td><td>Anthropic 宣称奇点已至·GDP 推高 44 万亿</td><td><strong>Jack Clark 个人</strong>对政策界讲话</td><td>2026-10-17/18</td><td>—</td><td>是<strong>GDP 总量</strong> 44 万亿，非增量</td></tr><tr><td>AI4</td><td>哈佛×谷歌称 GPT-6 Astra 解 98% 世界物理难题</td><td><strong>TheoPhysEval</strong> 基准（35 位研究者）</td><td>The Decoder 2026-10-15</td><td>—</td><td>是<strong>50 道选定题</strong>；删掉了&quot;缺 taste&quot;限定</td></tr><tr><td>地1</td><td>北极再创新低·南极意外大幅反弹</td><td>NASA / NSIDC</td><td>2026-09~10</td><td>—</td><td><strong>两边都错</strong>：北极并列<strong>第10低</strong>；南极<strong>第3低</strong>，&quot;reversal&quot;是<strong>向下</strong>逆转</td></tr><tr><td>地2</td><td>NASA 发现亚马逊地下&quot;隐藏火灾&quot;</td><td><strong>NASA Earth Observatory</strong></td><td>2026-10-15/16</td><td>—</td><td><strong>地理错配</strong>：泥炭地下阴燃属<strong>印尼</strong></td></tr></tbody></table><hr><h2 id="⚠️-本次核实推翻的两处初判-自我更正" tabindex="-1">⚠️ 本次核实推翻的两处初判（自我更正） <a class="header-anchor" href="#⚠️-本次核实推翻的两处初判-自我更正" aria-label="Permalink to &quot;⚠️ 本次核实推翻的两处初判（自我更正）&quot;">​</a></h2><ol><li><strong>罗马望远镜&quot;尚未发射&quot;</strong> → 错。它 <strong>2026-08-30 已发射入轨</strong>，10-22 进入科学调试阶段。</li><li><strong>南极海冰&quot;达到 2026 年度最大值（回升）&quot;</strong> → 错。南极 2026 冬季峰值是<strong>历史第 3 低</strong>；ScienceDaily 原文的 &quot;stunning reversal&quot; 指<strong>从创纪录高位翻转到近创纪录低位</strong>（向下），36kr 读成了&quot;反弹&quot;（向上）—— <strong>方向读反</strong>。</li></ol><hr><h2 id="🔴-ai-科技-4-条-·-失真最严重" tabindex="-1">🔴 AI 科技（4 条 · 失真最严重） <a class="header-anchor" href="#🔴-ai-科技-4-条-·-失真最严重" aria-label="Permalink to &quot;🔴 AI 科技（4 条 · 失真最严重）&quot;">​</a></h2><h3 id="ai1「openai-之后-ai-再破广义黎曼猜想」" tabindex="-1">AI1「OpenAI 之后，AI 再破广义黎曼猜想」 <a class="header-anchor" href="#ai1「openai-之后-ai-再破广义黎曼猜想」" aria-label="Permalink to &quot;AI1「OpenAI 之后，AI 再破广义黎曼猜想」&quot;">​</a></h3><ul><li><strong>原始报道</strong>：36Kr 英文站 <strong>2026-10-18</strong>《Bombshell Breakthrough! After OpenAI, AI Has Once Again Cracked the Generalized Riemann Hypothesis》</li><li><strong>真身</strong>：<strong>Anthropic 2026-08-10</strong> 的研究（比 36Kr 早 <strong>2 个月</strong>）</li><li><strong>真实内容</strong>（Kingy AI 2026-08-10 逐点解读，作者 Curtis Pyke）：原文开门第一句就是 <strong>&quot;Claude did not solve the Riemann hypothesis.&quot;</strong> —— Anthropic 称一个<strong>未发布</strong>的 Claude 模型协助证明了<strong>一个更窄的结果</strong>：<strong>至少 67.25% 的非平凡 ζ 零点在相关渐近意义下是单重的、且位于临界线上</strong>。公告只描述<strong>内部验证 + 短期专家评审</strong>，<strong>无同行评议记载</strong>；<strong>研究模型身份不公开，无法端到端复现</strong>。</li><li><strong>失真点</strong>：① &quot;破解广义黎曼猜想&quot; ❌（实为 67.25% 的窄结论）② 8 月旧闻当 10 月新闻 ③ 略过&quot;未同行评议 / 不可复现&quot;</li><li><strong>级别</strong>：✅ 已核实</li></ul><h3 id="ai2「chatgpt-升级-ai-小队-模式-多智能体分工干活-还能查进度」" tabindex="-1">AI2「ChatGPT 升级&quot;AI 小队&quot;模式：多智能体分工干活，还能查进度」 <a class="header-anchor" href="#ai2「chatgpt-升级-ai-小队-模式-多智能体分工干活-还能查进度」" aria-label="Permalink to &quot;AI2「ChatGPT 升级&quot;AI 小队&quot;模式：多智能体分工干活，还能查进度」&quot;">​</a></h3><ul><li><strong>原始报道</strong>：36Kr 2026-10-19</li><li><strong>真身</strong>：<strong>2026-09-29</strong> OpenAI 发布 <strong>Dots</strong>（always-on AI 智能体&quot;同事&quot;，各自带云电脑）+ <strong>ChatGPT Space</strong>（人机共享工作空间）+ Pages / Slides <ul><li>VentureBeat 2026-09-29《OpenAI launches Dots, always-on AI agent coworkers, and ChatGPT Space…》</li><li>Engadget 2026-09-29、TechCrunch 2026-09-29《…what feels a whole lot like ChatGPT&#39;s own office suite》、ZDNET 2026-09-29</li></ul></li><li><strong>失真点</strong>：时间错位（9-29 → 10-19 才报）；&quot;AI 小队&quot;是中文再包装，官方叫 <strong>Dots + Space</strong>；媒体普遍读作<strong>对标 Microsoft/Google Workspace 的办公套件</strong></li><li><strong>级别</strong>：✅ 已核实</li></ul><h3 id="ai3「anthropic-宣称-奇点已至-预测-ai-或将美国-gdp-推高-44-万亿美元」" tabindex="-1">AI3「Anthropic 宣称&quot;奇点已至&quot;，预测 AI 或将美国 GDP 推高 44 万亿美元」 <a class="header-anchor" href="#ai3「anthropic-宣称-奇点已至-预测-ai-或将美国-gdp-推高-44-万亿美元」" aria-label="Permalink to &quot;AI3「Anthropic 宣称&quot;奇点已至&quot;，预测 AI 或将美国 GDP 推高 44 万亿美元」&quot;">​</a></h3><ul><li><strong>原始报道</strong>：Yahoo Finance 2026-10-18；PYMNTS / Stocktwits；The Rundown AI 2026-10-22</li><li><strong>真实内容</strong>：说话人是<strong>联合创始人 Jack Clark 个人</strong>（不是&quot;Anthropic 公司&quot;），场合是<strong>对政策制定者</strong>讲话。原话口径：<strong>美国 GDP 到 2030 年迈向 44 万亿美元</strong>，即<strong>增长近 50%</strong>；&quot;The singularity is here&quot;。R&amp;D World 2026-10-23 记他称&quot;<strong>十亿个虚拟科学家即将到来——或者 100 亿</strong>&quot;。</li><li><strong>失真点</strong>：① &quot;Anthropic 宣称&quot; ❌（个人政策场合预测）② &quot;推高 44 万亿&quot; ❌（是 GDP <strong>总量</strong> 说到 44 万亿）③ ⚠️ 36Kr <strong>另一篇</strong>（10-17）竟写成&quot;<strong>Anthropic Valuation Hits $44 Trillion</strong>（Anthropic 估值达 44 万亿）&quot;—— <strong>纯错译</strong></li><li><strong>级别</strong>：✅ 已核实</li></ul><h3 id="ai4「哈佛×谷歌研究称-gpt-6-astra-已解决-98-世界物理难题-学界争议中」" tabindex="-1">AI4「哈佛×谷歌研究称 GPT-6 Astra 已解决 98% 世界物理难题，学界争议中」 <a class="header-anchor" href="#ai4「哈佛×谷歌研究称-gpt-6-astra-已解决-98-世界物理难题-学界争议中」" aria-label="Permalink to &quot;AI4「哈佛×谷歌研究称 GPT-6 Astra 已解决 98% 世界物理难题，学界争议中」&quot;">​</a></h3><ul><li><strong>原始报道</strong>：36Kr 2026-10-19；英文一手 The Decoder <strong>2026-10-15</strong>《GPT-6-Astra solves 49 of 50 physics research problems at <strong>$2.40</strong> apiece》（Maximilian Schreiner）</li><li><strong>真实内容</strong>：发布的是 <strong>TheoPhysEval</strong> 基准，由 <strong>35 位研究者</strong>发布，机构含 <strong>ICTS（国际理论科学中心）、哈佛大学、KU Leuven、Google DeepMind</strong>；基准含 <strong>50 道未发表的理论物理研究问题</strong>（带可验证答案）；<strong>GPT-6-Astra 解出 49/50</strong>，<strong>每题成本 $2.40</strong>。⚠️ 研究者<strong>关键限定</strong>：<strong>&quot;缺少 taste（品味）&quot;是突破尚未随之而来的原因之一</strong> —— 解出计算题 ≠ 做出研究突破。</li><li><strong>失真点</strong>：① &quot;世界物理难题&quot; ❌（50 道<strong>选定的、未发表的</strong>题）② &quot;98%&quot; 数字对（49/50）但语境被抽掉 ③ &quot;哈佛×谷歌研究称&quot; ❌（35 人跨国团队发布 benchmark，谷歌方是 DeepMind）④ <strong>完全省略&quot;缺 taste、突破未随之而来&quot;</strong> —— 这正是&quot;学界争议&quot;的真实内容</li><li><strong>级别</strong>：✅ 已核实</li><li>备注：GPT-6 Astra 在 2026-10 是真实主力模型（The Decoder 专题：接入机器人清理陌生厨房、<strong>10 小时破译 83 年未解的纳粹电文</strong>、UK AISI 测出其<strong>越狱攻击率比上代高 5 倍</strong>）</li></ul><hr><h2 id="🧬-生物医学-4-条" tabindex="-1">🧬 生物医学（4 条） <a class="header-anchor" href="#🧬-生物医学-4-条" aria-label="Permalink to &quot;🧬 生物医学（4 条）&quot;">​</a></h2><h3 id="生1「usc-团队找到无限量产抗癌免疫细胞的方法」" tabindex="-1">生1「USC 团队找到无限量产抗癌免疫细胞的方法」 <a class="header-anchor" href="#生1「usc-团队找到无限量产抗癌免疫细胞的方法」" aria-label="Permalink to &quot;生1「USC 团队找到无限量产抗癌免疫细胞的方法」&quot;">​</a></h3><ul><li><strong>真实来源</strong>：<strong>Cell</strong> 论文 <em>Expansion and CAR engineering of granulocyte-monocyte progenitors for cellular immunotherapy</em>，<strong>DOI <code>10.1016/j.cell.2026.05.043</code></strong>（2026 年 8 月期，在线约 6 月）；一手新闻稿 USC Keck / USC Stem Cell <strong>2026-06-19</strong>；二手 ScienceDaily 2026-10-16</li><li><strong>研究内容</strong>：USC Stem Cell <strong>Qi-Long Ying（应其龙）实验室</strong>（一作 Shi Yue）。不用成熟巨噬细胞，改为培养<strong>粒细胞-单核细胞祖细胞（GMP）</strong>，证明其可<strong>长期扩增并保持分化潜能</strong>（打破&quot;长期自我更新是造血干细胞专属&quot;的成见），再做 <strong>CAR 工程化</strong>。小鼠实验：工程化细胞在骨髓定植、持续产生新免疫细胞、减缓血液瘤与实体瘤进展。</li><li><strong>失真点</strong>：① &quot;无限量产/never-ending&quot;是 ScienceDaily 标题党，论文原话是 <em>long-term expansion / renewable and expandable supply</em> ② &quot;抗癌免疫细胞&quot;实为 <strong>CAR-巨噬细胞</strong>（非 CAR-T），中文丢了关键限定 ③ 只是<strong>临床前</strong>（小鼠 + 人细胞体外） ④ 时间错位（6 月 → 10 月中 ScienceDaily 再推送）</li><li><strong>级别</strong>：✅ 已核实</li></ul><h3 id="生2「等了-30-年-致命脑病-foxd1-相关神经退行性疾病-终于迎来首个有效药物」" tabindex="-1">生2「等了 30 年，致命脑病（FOXD1 相关神经退行性疾病）终于迎来首个有效药物」 <a class="header-anchor" href="#生2「等了-30-年-致命脑病-foxd1-相关神经退行性疾病-终于迎来首个有效药物」" aria-label="Permalink to &quot;生2「等了 30 年，致命脑病（FOXD1 相关神经退行性疾病）终于迎来首个有效药物」&quot;">​</a></h3><ul><li><strong>真实来源</strong>：FDA <strong>2026-09-03</strong> 批准 <strong>Zanvastro（通用名 zilganersen）</strong>；Ionis 官方 IR 页 <code>ZANVASTRO™ FDA Approval</code>（2026-09-04）；UW–Madison News 2026-09-18；STAT 2026-09-03；<strong>Reuters 2026-09-04 定价 $285,000/剂</strong>；ScienceDaily 2026-10-12</li><li><strong>研究内容</strong>：<strong>Alexander 病（AxD）</strong>，由 <strong>GFAP 基因</strong>（胶质纤维酸性蛋白）功能获得性突变引起的超罕见（&lt;1/百万）致死性<strong>白质营养不良</strong>。<strong>Albee Messing（UW–Madison Waisman Center）</strong> 1990 年代末定位病因；30+ 年后与 Ionis 做出<strong>反义寡核苷酸（ASO）</strong>，抑制 GFAP 生成，<strong>鞘内注射每 3 个月一次</strong>。临床试验中患者运动功能<strong>稳定</strong>（部分改善）。</li><li><strong>失真点</strong>：① <strong>基因名错</strong> —— 写成 <strong>FOXD1</strong> ❌（与本病无关；实为 <strong>GFAP</strong>）② &quot;首个有效药物&quot;应表述为&quot;<strong>首个且唯一疾病修饰治疗</strong>&quot;，疗效是&quot;<strong>运动功能稳定</strong>&quot;而非无保留&quot;有效&quot;</li><li><strong>级别</strong>：✅ 已核实</li></ul><h3 id="生3「新药通过修复肠道菌群逆转严重脂肪肝」" tabindex="-1">生3「新药通过修复肠道菌群逆转严重脂肪肝」 <a class="header-anchor" href="#生3「新药通过修复肠道菌群逆转严重脂肪肝」" aria-label="Permalink to &quot;生3「新药通过修复肠道菌群逆转严重脂肪肝」&quot;">​</a></h3><ul><li><strong>真实来源</strong>：<strong>J Clin Invest</strong> 2026;136(13):e200522，<strong>DOI <code>10.1172/JCI200522</code></strong>，<em>Metabolic dysfunction-associated steatohepatitis exacerbated by Clostridium perfringens-derived ammonia is attenuated by tripeptide DT-109</em>；同刊配评 DOI <code>10.1172/JCI207921</code>；ScienceDaily 2026-07-11 与 2026-10-16</li><li><strong>研究内容</strong>：药物 <strong>DT-109</strong>（甘氨酸三肽；密歇根大学 Chen YE 实验室 / Diapin Therapeutics；本论文第一单位西安交通大学 + 密歇根大学合作）。机制：MASH 中产氨菌 **产气荚膜梭菌（C. perfringens）**增多 → 肠道氨升高 → 破坏肠屏障、经 <strong>FosB 上调 CD8⁺ T 细胞的 CCL5</strong> → 肝细胞毒。DT-109 降低该菌、降肠道氨、修复肠屏障、改善 CD8⁺ T 失调。模型：人队列 + <strong>非人灵长类 + 小鼠</strong>。</li><li><strong>失真点</strong>：① &quot;修复肠道菌群&quot;更确切是&quot;<strong>抑制产氨的产气荚膜梭菌 + 降氨 + 修肠屏障</strong>&quot; ② &quot;逆转&quot;来自 ScienceDaily 标题，论文用 <em>alleviated/ameliorating</em>，且以机制 + 动物模型为主，非临床疗效 ③ 源头可追溯到更早研究，中文写成&quot;新药&quot;单点突破</li><li><strong>级别</strong>：✅ 已核实</li></ul><h3 id="生4「47-年追踪研究首次锁定-肌肉力量从这一个年龄开始加速流失」" tabindex="-1">生4「47 年追踪研究首次锁定：肌肉力量从这一个年龄开始加速流失」 <a class="header-anchor" href="#生4「47-年追踪研究首次锁定-肌肉力量从这一个年龄开始加速流失」" aria-label="Permalink to &quot;生4「47 年追踪研究首次锁定：肌肉力量从这一个年龄开始加速流失」&quot;">​</a></h3><ul><li><strong>真实来源</strong>：<strong>J Cachexia Sarcopenia Muscle</strong> 2025;16(6):e70134，<strong>DOI <code>10.1002/jcsm.70134</code></strong>，<em>Rise and Fall of Physical Capacity in a General Population: A 47-Year Longitudinal Study</em>（Karolinska Institutet；PMID 41243424）；ScienceDaily 2026-10-14</li><li><strong>研究内容</strong>：瑞典 <strong>SPAF 队列</strong>，<strong>427 人（48% 女性，1958 年生）</strong>，<strong>16→63 岁重复客观测量</strong>。有氧能力 / 肌肉耐力（卧推次数）<strong>26–36 岁达峰</strong>；爆发力（Sargent 跳）男 27 岁、女 19 岁达峰。下降初期 <strong>0.3–0.6%/年</strong>，<strong>加速到 2.0–2.5%/年</strong>；峰值到 63 岁总降 <strong>30–48%</strong>。结论：体能衰退<strong>40 岁前</strong>即出现。</li><li><strong>失真点</strong>：① &quot;从<strong>这一个</strong>年龄开始加速&quot; —— 单一&quot;35 岁&quot;是 ScienceDaily 简化，论文是<strong>区间 26–36 岁达峰 + 渐进下降</strong> ② &quot;肌肉力量&quot;不精确，实为<strong>有氧 + 肌耐力 + 爆发力</strong>三类&quot;体能&quot; ③ &quot;<strong>首次</strong>锁定&quot;夸大 —— 运动员中早已知峰值在 35 岁前，本研究是在<strong>普通人群中确认同一模式</strong></li><li><strong>级别</strong>：✅ 已核实</li></ul><hr><h2 id="🚀-太空物理-4-条" tabindex="-1">🚀 太空物理（4 条） <a class="header-anchor" href="#🚀-太空物理-4-条" aria-label="Permalink to &quot;🚀 太空物理（4 条）&quot;">​</a></h2><h3 id="太1「nasa-罗马望远镜日冕仪-开光-成功-性能超出设计预期近-30-」" tabindex="-1">太1「NASA 罗马望远镜日冕仪&quot;开光&quot;成功，性能超出设计预期近 30%」 <a class="header-anchor" href="#太1「nasa-罗马望远镜日冕仪-开光-成功-性能超出设计预期近-30-」" aria-label="Permalink to &quot;太1「NASA 罗马望远镜日冕仪&quot;开光&quot;成功，性能超出设计预期近 30%」&quot;">​</a></h3><ul><li><strong>真实来源</strong>：NASA Roman blog <strong>2026-10-14</strong>《NASA Roman Team Checks Out Main Instrument, Sharpens Telescope&#39;s Focus》（Ashley Balzer）；<strong>2026-10-22</strong>《…Enters Final Commissioning Phase》；<strong>2026-09-30</strong>《NASA Checks Roman Guidance System, Takes First Coronagraph Observation》；SciTechDaily 2026-10-20</li><li><strong>真实内容</strong>：Roman <strong>2026-08-30 已发射入轨</strong>，现处<strong>在轨调试（commissioning）</strong>，10-22 进入<strong>科学调试阶段</strong>。工程师先修正<strong>日冕仪（Coronagraph Instrument）<strong>的轻微离焦；随后调整</strong>宽视场仪（WFI）</strong> —— WFI 光学波前误差要求 <strong>~90 nm RMS，实测 63 nm RMS</strong>，即&quot;比预测好近 30%&quot;。日冕仪<strong>首次观测</strong>见 2026-09-30 博客。</li><li><strong>失真点</strong>：① <strong>张冠李戴（最关键）</strong> —— 90→63 nm 的&quot;近 30%&quot;属 <strong>WFI</strong>，中文安给了<strong>日冕仪</strong> ② 与事实相反：日冕仪恰恰是&quot;一度轻微失焦、校正后<strong>达到团队预期</strong>&quot;，<strong>并未超预期</strong> ③ &quot;直接成像时代加速到来&quot;属评论性拔高</li><li><strong>级别</strong>：✅ 已核实</li></ul><h3 id="太2「天文学家预测-两个巨型黑洞正螺旋接近-最快约-100-年内相撞并释放引力波」" tabindex="-1">太2「天文学家预测：两个巨型黑洞正螺旋接近，最快约 100 年内相撞并释放引力波」 <a class="header-anchor" href="#太2「天文学家预测-两个巨型黑洞正螺旋接近-最快约-100-年内相撞并释放引力波」" aria-label="Permalink to &quot;太2「天文学家预测：两个巨型黑洞正螺旋接近，最快约 100 年内相撞并释放引力波」&quot;">​</a></h3><ul><li><strong>真实来源</strong>：德国<strong>马克斯·普朗克射电天文研究所（MPIfR, Bonn）</strong>，团队负责人 <strong>Silke Britzen</strong>；期刊 <strong>MNRAS（已接收待刊）</strong>。ScienceDaily 2026-10-18；Phys.org <strong>2026-04-07</strong>《First close pair of supermassive black holes detected》；Live Science 2026-04-16</li><li><strong>真实内容</strong>：星系 <strong>Markarian 501 (Mrk 501)</strong> 中心；用约 <strong>23 年、多频率射电观测</strong>发现一条此前未见到的<strong>第二条喷流</strong>（被前景黑洞引力透镜成&quot;爱因斯坦环&quot;），据此推断存在第二个超大质量黑洞；两黑洞轨道周期约 <strong>121 天</strong>；依质量不同&quot;最快约 100 年内并合&quot;。</li><li><strong>失真点</strong>：① 第二黑洞是<strong>间接推断</strong>（喷流 + 透镜）而非直接成像 ② &quot;预测相撞&quot;实为&quot;<strong>compelling evidence 提示</strong>一对黑洞存在，并合时标依质量而定（100 年为乐观下限）&quot; ③ 中文省略了&quot;<strong>单一星系 Mrk 501</strong>&quot;这一关键限定 ④ 时间错位（4 月已首发） ⑤ DOI 未入 CrossRef（接收稿）</li><li><strong>级别</strong>：✅ 已核实（机构/期刊/日期/数字；DOI 未核实）</li></ul><h3 id="太3「首台核时钟-基于钍-229-问世-精度有望超越现有原子钟-重新定义-秒-」" tabindex="-1">太3「首台核时钟（基于钍-229）问世，精度有望超越现有原子钟，重新定义&quot;秒&quot;」 <a class="header-anchor" href="#太3「首台核时钟-基于钍-229-问世-精度有望超越现有原子钟-重新定义-秒-」" aria-label="Permalink to &quot;太3「首台核时钟（基于钍-229）问世，精度有望超越现有原子钟，重新定义&quot;秒&quot;」&quot;">​</a></h3><ul><li><strong>真实来源</strong>：<strong>同日（2026-10-07）《Nature》两篇独立论文</strong>： <ul><li>《A thorium-229 optical nuclear clock with feedback loop》，Nature <strong>658, 897–902</strong>，<strong>DOI <code>10.1038/s41586-026-11084-4</code></strong> —— 维也纳团队（TU Wien / PTB；T. Schumm、E. Peik 等）</li><li>《A nuclear clock synchronized to ²²⁹Th》，Nature <strong>658, 903–908</strong>，<strong>DOI <code>10.1038/s41586-026-11122-1</code></strong> —— 中国团队（中科院精密测量院 / 武汉、北大等；Li You、Shiqian Ding 等）</li><li>二次：NYT 2026-10-07；SCMP 2026-10-07《China&#39;s thorium-229 nuclear clock beats Vienna&#39;s on stability》</li></ul></li><li><strong>真实内容</strong>：将连续波激光锁定到 ²²⁹Th 核的 <strong>148 nm 核跃迁</strong>（快速反馈 / 反馈环），建成&quot;核钟&quot;；核跃迁对外部扰动更稳健、对基础物理检验更敏感。</li><li><strong>失真点</strong>：① &quot;<strong>首台</strong>&quot;不成立 —— 是<strong>两家同日各自独立实现</strong>（维也纳 + 中国） ② &quot;精度有望超越现有原子钟&quot;是 <strong>candidate / expected</strong>，非已验证事实 ③ &quot;<strong>重新定义&quot;秒&quot;</strong>&quot;属<strong>远期设想</strong></li><li><strong>级别</strong>：✅ 已核实（期刊 + DOI + 日期 + 团队；稳定度具体数值未核实）</li></ul><h3 id="太4「nasa-启动月球洞穴勘探-熔岩管或成首个月球基地的天然防辐射掩体」" tabindex="-1">太4「NASA 启动月球洞穴勘探，熔岩管或成首个月球基地的天然防辐射掩体」 <a class="header-anchor" href="#太4「nasa-启动月球洞穴勘探-熔岩管或成首个月球基地的天然防辐射掩体」" aria-label="Permalink to &quot;太4「NASA 启动月球洞穴勘探，熔岩管或成首个月球基地的天然防辐射掩体」&quot;">​</a></h3><ul><li><strong>真实来源</strong>：NASA 选中 <strong>PSI（Planetary Science Institute）牵头的 GIMLI</strong> 项目（Geophysical Instruments for Marius Lunar pit Investigation），<strong>2026-09-30 宣布</strong>；NASA 2026-10-02；EurekAlert 2026-10-02；Astronomy 2026-10-09。负责人 <strong>Than Putzig (PSI)</strong></li><li><strong>真实内容</strong>：目标 <strong>Marius Hills Pit</strong>（约 <strong>65×90 m</strong>，位于 Oceanus Procellarum）；用<strong>着陆器 + 巡视器</strong>搭载<strong>探地雷达 + 主动震源地震仪 + 重力仪 + 相机</strong>，探测洞口是否连通大型熔岩管，或成&quot;首次获得月球熔岩管地面直接证据&quot;。NASA 原文称这些地下洞穴&quot;<strong>有朝一日可为宇航员遮挡辐射与极端温差</strong>&quot;。</li><li><strong>失真点</strong>：① &quot;<strong>启动勘探</strong>&quot;失真 → 目前仅<strong>立项 / 被选中</strong>，探测器尚未发射 ② &quot;熔岩管&quot;在月球<strong>至今从未被证实</strong>，中文表述偏确定 ③ &quot;天然防辐射掩体&quot;有原文依据，但属&quot;<strong>could one day</strong>&quot;的未来可能性</li><li><strong>级别</strong>：✅ 已核实</li></ul><hr><h2 id="⚡-材料能源-4-条" tabindex="-1">⚡ 材料能源（4 条） <a class="header-anchor" href="#⚡-材料能源-4-条" aria-label="Permalink to &quot;⚡ 材料能源（4 条）&quot;">​</a></h2><h3 id="材1「科学家发现从水制氢的新催化路径-绿氢成本再降一步」" tabindex="-1">材1「科学家发现从水制氢的新催化路径，绿氢成本再降一步」 <a class="header-anchor" href="#材1「科学家发现从水制氢的新催化路径-绿氢成本再降一步」" aria-label="Permalink to &quot;材1「科学家发现从水制氢的新催化路径，绿氢成本再降一步」&quot;">​</a></h3><ul><li><strong>真实来源</strong>：<strong>JACS</strong> <em>Intraligand Charge Transfer in Metal-Organic Frameworks Facilitates Radical Anion-Mediated Hydrogen Evolution</em>，<strong>2026-09-14</strong>，<strong>DOI <code>10.1021/jacs.6c13238</code></strong>；俄勒冈州立大学 <strong>Kyriakos C. Stylianou</strong>（MaD Lab 主任），一作 Emmanuel Nyela Musa；OSU 新闻稿 2026-09-28；ScienceDaily 2026-10-04</li><li><strong>真实内容</strong>：开发一类<strong>光催化 MOF 材料</strong>（主角 <strong>BVR-19</strong>）。关键机理：光照<strong>暂时断裂材料内的 S–S（硫–硫）键</strong>，产生高活性硫自由基/自由基阴离子，驱动水分解产氢 —— <strong>电子转移主要由有机硫配体承担，而非金属中心</strong>，因此<strong>无需昂贵的金属助催化剂</strong>，且 BVR-19 可在<strong>室温水溶液中自发合成</strong>。论文只给了绿氢&quot;约 $5/kg&quot; vs 甲烷重整&quot;约 $1.50/kg&quot;的<strong>行业现状价差</strong>，<strong>全文未给出新材料自身的产氢速率/成本数字</strong>。</li><li><strong>失真点</strong>：① &quot;<strong>绿氢成本再降一步</strong>&quot; → <strong>夸大</strong>，论文只提&quot;设计规则/蓝图&quot;，<strong>无任何实测成本下降</strong> ② &quot;新催化路径&quot;基本准确</li><li><strong>级别</strong>：✅ 已核实</li></ul><h3 id="材2「单原子厚的-量子高速公路-问世-超导电流承载能力突破传统极限」" tabindex="-1">材2「单原子厚的&quot;量子高速公路&quot;问世，超导电流承载能力突破传统极限」 <a class="header-anchor" href="#材2「单原子厚的-量子高速公路-问世-超导电流承载能力突破传统极限」" aria-label="Permalink to &quot;材2「单原子厚的&quot;量子高速公路&quot;问世，超导电流承载能力突破传统极限」&quot;">​</a></h3><ul><li><strong>真实来源</strong>：<strong>Physical Review B</strong> vol. 114，<strong>2026-07-30</strong>，<strong>DOI <code>10.1103/b2j3-xj19</code></strong>，<em>Anisotropic transport of Josephson vortices in atomic-layer superconductors on vicinal surfaces</em>；日本<strong>物质·材料研究机构（NIMS）MANA 研究中心</strong>，通讯 <strong>Takashi Uchihashi（内橋隆）</strong>；ScienceDaily 2026-10-16</li><li><strong>真实内容</strong>：研究对象是<strong>原子层厚度的超导薄膜</strong>，表面有<strong>仅一个原子高的规则台阶</strong>。用<strong>扫描隧道显微镜（STM）<strong>确认台阶平行排列并观察到</strong>量子涡旋沿台阶排布</strong>；用<strong>四端电阻测量</strong>量化涡旋运动各向异性。关键数字：中磁场下涡旋<strong>沿台阶方向的移动比垂直方向容易 1000 倍以上</strong>；<strong>0.10–0.20 T</strong> 区间出现&quot;<strong>一维无钉扎涡旋流</strong>&quot;；极低温下涡旋运动由<strong>量子隧穿</strong>主导。</li><li><strong>失真点（本条失真最严重）</strong>：① 「<strong>超导电流承载能力突破传统极限</strong>」 → <strong>定性错误</strong>。研究讲的是<strong>量子涡旋的各向异性运动</strong>，而涡旋运动恰恰是<strong>产生电阻</strong>的来源；论文<strong>根本没有</strong>宣称提高临界电流或&quot;电流承载能力&quot; ② 「<strong>量子高速公路</strong>」→ <strong>比喻失当</strong>，原文的&quot;轨道/护栏&quot;指<strong>引导涡旋</strong>（而非载流电子）沿台阶走 ③ 「单原子厚」混淆两个尺度：超导体是&quot;原子层厚度&quot;，&quot;一个原子高&quot;指的是<strong>台阶高度</strong></li><li><strong>级别</strong>：✅ 已核实</li></ul><h3 id="材3「ai-挖掘出-co2→燃料的隐藏化学反应捷径-碳转化效率大幅提升」" tabindex="-1">材3「AI 挖掘出 CO₂→燃料的隐藏化学反应捷径，碳转化效率大幅提升」 <a class="header-anchor" href="#材3「ai-挖掘出-co2→燃料的隐藏化学反应捷径-碳转化效率大幅提升」" aria-label="Permalink to &quot;材3「AI 挖掘出 CO₂→燃料的隐藏化学反应捷径，碳转化效率大幅提升」&quot;">​</a></h3><ul><li><strong>真实来源</strong>：<strong>Nature Communications</strong>，<strong>2026-09-17</strong>，<strong>DOI <code>10.1038/s41467-026-77080-4</code></strong>，<em>Data-driven massive reaction networks reveal mechanistic pathways underlying catalytic CO2 hydrogenation</em>；印度理工学院（<strong>IISc</strong>），一作 Anand Mohan Verma，通讯 <strong>Ananth Govind Rajan</strong>；实验验证由印度斯坦石油公司（HPCL）与新加坡 A*STAR 完成；SciTechDaily 2026-10-10；gasworld 2026-10-14</li><li><strong>真实内容</strong>：用<strong>量子力学模拟</strong>先建 152 个反应的&quot;可信小网络&quot;，再用<strong>机器学习模型预测活化能垒</strong>，在铜催化剂表面 <strong>105 种物种</strong>间穷举单步反应，把网络<strong>扩展到 9,389 个基元反应</strong>，再塞进动力学模型计算。关键数字：<strong>9,389 vs 152</strong>；扩展后模型预测的 <strong>CO₂ 转化量约为原来的 40 倍</strong>，并<strong>正确预测出甲醇和 CO 为主要产物</strong>（小网络错误预测为甲酸）。副产物发现：氢可以<strong>以完整 H₂ 分子直接转移</strong>到中间体（而非必须解离成氢原子）。</li><li><strong>失真点</strong>：① 「<strong>碳转化效率大幅提升</strong>」 → <strong>误导</strong>，那个&quot;40 倍&quot;是<strong>模型预测的 CO₂ 转化量变化</strong>（网络保真度提升），<strong>非实验测得产率</strong>；研究<strong>没有制造新催化剂</strong> ② 「<strong>AI 挖掘</strong>」部分失真 —— ML 只负责预测活化能垒一环 ③ 「隐藏化学反应捷径」措辞不准 —— 是<strong>机理性发现</strong>（H₂ 以完整分子转移）</li><li><strong>级别</strong>：✅ 已核实</li></ul><h3 id="材4「新量子比特将错误率降低-100-倍-超流体量子计算迈出关键一步」" tabindex="-1">材4「新量子比特将错误率降低 100 倍，超流体量子计算迈出关键一步」 <a class="header-anchor" href="#材4「新量子比特将错误率降低-100-倍-超流体量子计算迈出关键一步」" aria-label="Permalink to &quot;材4「新量子比特将错误率降低 100 倍，超流体量子计算迈出关键一步」&quot;">​</a></h3><ul><li><strong>真实来源</strong>：<strong>npj Quantum Information</strong>，<strong>2026-08-24</strong>，<strong>DOI <code>10.1038/s41534-026-01355-3</code></strong>，<em>Towards a micromechanical qubit based on quantized oscillations in superfluid helium</em>；英国**萨里大学（University of Surrey）**量子科学组，一作 <strong>Priya Sharma</strong>（Daphne Jackson Fellow），共同作者 Eran Ginossar，合作者 Jens Koch（西北大学，transmon 设计者之一）；Newswise 2026-09-11；ScienceDaily 2026-10-01</li><li><strong>真实内容</strong>：提出一种<strong>基于超流氦-3 的全新量子比特设计方案</strong>，命名 <strong>SHOQ（Superfluid Helium Oscillator Quantum）</strong>，把超流氦的量子化振荡集成进<strong>微流控器件</strong>当量子比特。因超流氦<strong>电中性</strong>，理论上<strong>天然免疫部分电磁噪声</strong>。关键数字：计算<strong>预测其错误率比传统超导量子比特低约 100 倍</strong>。⚠️ <strong>极关键</strong>：这是<strong>全球首个&quot;超流体量子比特&quot;设计方案（concept）</strong>，论文结论是&quot;<strong>数学上应该成立，下一步要做原型验证</strong>&quot; —— <strong>器件尚未制造</strong>。</li><li><strong>失真点</strong>：① 「<strong>新量子比特</strong>」→ 夸大，是<strong>尚未实现的设计提案</strong>（原题以 <em>Towards…</em> 开头） ② 「<strong>将错误率降低 100 倍</strong>」→ <strong>把预测当事实</strong>，作者自己说要造原型验证 ③ 「迈出关键一步」基本公允但易被读成&quot;已实现&quot;</li><li><strong>级别</strong>：✅ 已核实</li></ul><hr><h2 id="🌍-地球环境-2-条" tabindex="-1">🌍 地球环境（2 条） <a class="header-anchor" href="#🌍-地球环境-2-条" aria-label="Permalink to &quot;🌍 地球环境（2 条）&quot;">​</a></h2><h3 id="地1「北极海冰-2026-年再创新低-南极海冰却意外大幅反弹-两极分化成谜」" tabindex="-1">地1「北极海冰 2026 年再创新低，南极海冰却意外大幅反弹，两极分化成谜」 <a class="header-anchor" href="#地1「北极海冰-2026-年再创新低-南极海冰却意外大幅反弹-两极分化成谜」" aria-label="Permalink to &quot;地1「北极海冰 2026 年再创新低，南极海冰却意外大幅反弹，两极分化成谜」&quot;">​</a></h3><ul><li><strong>真实来源</strong>：NASA《Arctic Sea Ice Reaches 2026 Annual Minimum Extent》<strong>2026-09-23</strong>；NASA《Antarctic Sea Ice Grows to Its 2026 Maximum》<strong>2026-10-13</strong>；NSIDC《&quot;Stranger Things&quot; in the 2026 Arctic》2026-10-07；NASA/NSIDC《Arctic Winter Sea Ice Ties Record Low》2026-03-26；ScienceDaily 2026-10-16；Carbon Brief 2026-09-25</li><li><strong>真实内容（4 个数据点）</strong>： <ul><li>北极 <strong>2026 年最小</strong>（9/12）= <strong>4.6 M km²，与 2008/2010/2025 并列第 10 低</strong>（<strong>不是新低</strong>）</li><li>北极 <strong>2026 年冬季最大</strong>（3 月）<strong>并列历史最低</strong> ← 中文&quot;创新低&quot;的真实所指是&quot;最大&quot;</li><li>南极 <strong>2026 年夏季最小</strong>（2/26）= <strong>2.58 M km²，接近常年平均</strong>（&quot;反弹&quot;说法的来源；但 NSIDC 明言&quot;更健康的极小值 ≠ 恢复证据&quot;）</li><li>南极 <strong>2026 年冬季峰值 = 历史第 3 低</strong>；<strong>10 月初起日海冰面积创历史新低</strong></li></ul></li><li><strong>失真点</strong>：① 「北极 <strong>再创新低</strong>」→ <strong>错误</strong>（2026 年北极夏季最小仅第 10 低；只有<strong>冬季最大</strong>并列最低，中文把&quot;最大&quot;混淆成&quot;新低&quot;）② 「南极<strong>大幅反弹</strong>」→ <strong>方向读反</strong>：ScienceDaily 原标题 <em>Antarctica&#39;s sea ice has undergone a <strong>stunning reversal</strong></em> 的 &quot;reversal&quot; 指<strong>从创纪录高位翻转到近创纪录低位（向下）</strong>；中文读成了&quot;反弹（向上）&quot;。且南极冬季峰值实为<strong>第 3 低</strong> ③ 「两极分化成谜」属修辞</li><li><strong>级别</strong>：✅ 已核实到原报道，<strong>中文结论与原始数据相反</strong>（两断言各自被裁剪 + 时段错配后拼贴）</li></ul><h3 id="地2「nasa-卫星发现亚马逊雨林地下-隐藏火灾-激增-泥炭地下阴燃难以扑灭」" tabindex="-1">地2「NASA 卫星发现亚马逊雨林地下&quot;隐藏火灾&quot;激增，泥炭地下阴燃难以扑灭」 <a class="header-anchor" href="#地2「nasa-卫星发现亚马逊雨林地下-隐藏火灾-激增-泥炭地下阴燃难以扑灭」" aria-label="Permalink to &quot;地2「NASA 卫星发现亚马逊雨林地下&quot;隐藏火灾&quot;激增，泥炭地下阴燃难以扑灭」&quot;">​</a></h3><ul><li><strong>真实来源</strong>：<strong>NASA Earth Observatory《Fires Arrive in the Amazon Rainforest》2026-10-15/16</strong>（<code>science.nasa.gov/earth/earth-observatory/fires-arrive-in-the-amazon-rainforest/</code>）；ScienceDaily 2026-10-17（署名 NASA Earth Observatory，MODIS 数据）</li><li><strong>真实内容</strong>：2026 El Niño 干旱下的热带&quot;<strong>火链（cascade）</strong>&quot; —— <strong>先在印度尼西亚</strong>爆发地表 + <strong>地下泥炭阴燃</strong>火灾，再传导至亚马逊。亚马逊自 2026-09 起中东部火活动与烟雾激增，范围从 Manaus、Santarém 周边至亚马逊河口；2026-10-12 Aqua/MODIS 影像显示两岸浓烟，<strong>Manaus 空气 PM2.5 &gt; 135 µg/m³、学校停课</strong>。Douglas Morton（NASA Goddard）解释 cascade；Shane Coffield（UMD/NASA Goddard）：仅 <strong>Santarém 一带估计约 50–70 起</strong>失控火灾，多由<strong>人为点火（清灌/清茬）逃逸</strong>后蔓延进<strong>林下层（understory）</strong>。</li><li><strong>失真点</strong>：① ⚠️ <strong>地点张冠李戴（最关键）</strong> —— 真正&quot;<strong>地下/泥炭阴燃</strong>&quot;的是<strong>印度尼西亚</strong>；亚马逊是<strong>地表 / 林下层</strong>火灾，且部分是<strong>被卫星漏检</strong>（&quot;fires satellites miss&quot; / &quot;previously undetected&quot;）；中文把印尼的&quot;泥炭地下阴燃&quot;直接套到亚马逊 ② 「地下&#39;隐藏火灾&#39;<strong>激增</strong>」→ 原文是&quot;数十起此前未被探测到的火（主要林下 / 卫星漏检）&quot;，<strong>不是地下泥炭火</strong></li><li><strong>级别</strong>：✅ 已核实（NASA EO 一手页 + 数字）；<strong>中文转述存在关键地理错配</strong></li></ul><hr><h2 id="🧭-贯穿规律-比单条结论更有用" tabindex="-1">🧭 贯穿规律（比单条结论更有用） <a class="header-anchor" href="#🧭-贯穿规律-比单条结论更有用" aria-label="Permalink to &quot;🧭 贯穿规律（比单条结论更有用）&quot;">​</a></h2><ol><li><strong>中文&quot;科学日报&quot;是二手转译</strong>：多条可追溯到 2026-06~07 的原始新闻稿（Cell/USC 6月、JCI/DT-109 5月、JCSM 2025年见刊），10 月中被 ScienceDaily <strong>再推送</strong>后进入中文&quot;日报&quot; → <strong>8/18 条是旧闻重发</strong>。</li><li><strong>ScienceDaily 标题本身就是第一层失真源</strong>：「never-ending」「reversed」「this one age」「stunning reversal」这些措辞被中文直译后，失真被放大一层。<strong>尤其是 &quot;reversal&quot; 被读反方向</strong>。</li><li><strong>失真几乎都发生在转述环节</strong>，原始研究/机构/数字绝大多数真实存在：① 仪器张冠李戴（太1）② 季节/时段错配（地1）③ <strong>地理错配</strong>（地2）④ 唯一性拔高（太3、生4）⑤ &quot;立项&quot;说成&quot;已启动&quot;（太4）⑥ <strong>预测/模型输出说成已实现</strong>（材1/3/4）⑦ <strong>定性错误</strong>（材2：涡旋运动 → 电流承载）。</li><li><strong>凡&quot;突破 / 首个 / 破解 / 再创新低&quot;字样的，先查发布日期和原文措辞</strong> —— 本轮 18 条中，18 条都有据可查，<strong>0 条是纯编造</strong>，但<strong>没有一条</strong>原文真的做出了中文标题所宣称的成果。</li></ol><hr><p><em>核实时间：2026-10-23 · 方法：Google News RSS + 原文抓取 + CrossRef + PubMed · 18/18 均有真实出处</em></p>',61)])])}const h=o(g,[["render",e]]);export{q as __pageData,h as default};
